using System.Security.Cryptography;
using GestionMagasin.Domain;
using Microsoft.Data.Sqlite;

namespace GestionMagasin.Infrastructure;

public static class PasswordHasher
{
    private const int Iterations = 210_000; private const int SaltSize = 16; private const int KeySize = 32;
    public static string Hash(string password) { if (string.IsNullOrWhiteSpace(password)) throw new DomainException("Le mot de passe est obligatoire."); var salt=RandomNumberGenerator.GetBytes(SaltSize); var key=Rfc2898DeriveBytes.Pbkdf2(password,salt,Iterations,HashAlgorithmName.SHA256,KeySize); return $"PBKDF2-SHA256:{Iterations}:{Convert.ToBase64String(salt)}:{Convert.ToBase64String(key)}"; }
    public static bool Verify(string password, string encoded) { try { var p=encoded.Split(':'); if(p.Length!=4 || p[0]!="PBKDF2-SHA256") return false; var key=Rfc2898DeriveBytes.Pbkdf2(password,Convert.FromBase64String(p[2]),int.Parse(p[1]),HashAlgorithmName.SHA256,KeySize); return CryptographicOperations.FixedTimeEquals(key,Convert.FromBase64String(p[3])); } catch { return false; } }
}

public sealed class SqliteUserRepository(SqliteConnectionFactory factory) : IUtilisateurRepository
{
    public async Task<Utilisateur?> GetByIdAsync(Guid id, CancellationToken ct = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,NomUtilisateur,NomComplet,Role,Actif FROM Utilisateur WHERE Id=$id"; cmd.Parameters.AddWithValue("$id",id.ToString()); await using var r=await cmd.ExecuteReaderAsync(ct); return await r.ReadAsync(ct)?Read(r):null; }
    public async Task<Utilisateur?> AuthentifierAsync(string nom, string motDePasse, CancellationToken ct = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,NomUtilisateur,NomComplet,Role,Actif,PasswordHash FROM Utilisateur WHERE NomUtilisateur=$nom"; cmd.Parameters.AddWithValue("$nom",nom); await using var r=await cmd.ExecuteReaderAsync(ct); if(!await r.ReadAsync(ct) || !PasswordHasher.Verify(motDePasse, r.GetString(5))) return null; return Read(r); }
    public async Task<IReadOnlyList<Utilisateur>> ListerAsync(CancellationToken ct = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,NomUtilisateur,NomComplet,Role,Actif FROM Utilisateur ORDER BY NomUtilisateur"; var list=new List<Utilisateur>(); await using var r=await cmd.ExecuteReaderAsync(ct); while(await r.ReadAsync(ct)) list.Add(Read(r)); return list; }
    public async Task AjouterAsync(Utilisateur u, string motDePasse, CancellationToken ct = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="INSERT INTO Utilisateur(Id,NomUtilisateur,NomComplet,Role,Actif,CreeLeUtc,ModifieLeUtc,PasswordHash) VALUES($id,$login,$nom,$role,$actif,$now,$now,$hash)"; Add(cmd,u,motDePasse); await cmd.ExecuteNonQueryAsync(ct); }
    public async Task ModifierAsync(Utilisateur u, string? nouveauMotDePasse, CancellationToken ct = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText=nouveauMotDePasse is null?"UPDATE Utilisateur SET NomComplet=$nom,Role=$role,Actif=$actif,ModifieLeUtc=$now WHERE Id=$id":"UPDATE Utilisateur SET NomComplet=$nom,Role=$role,Actif=$actif,ModifieLeUtc=$now,PasswordHash=$hash WHERE Id=$id"; cmd.Parameters.AddWithValue("$id",u.Id.ToString()); cmd.Parameters.AddWithValue("$nom",u.NomComplet); cmd.Parameters.AddWithValue("$role",u.Role); cmd.Parameters.AddWithValue("$actif",u.Actif?1:0); cmd.Parameters.AddWithValue("$now",DateTime.UtcNow.ToString("O")); if(nouveauMotDePasse is not null) cmd.Parameters.AddWithValue("$hash",PasswordHasher.Hash(nouveauMotDePasse)); await cmd.ExecuteNonQueryAsync(ct); }
    public async Task<bool> ExisteAdministrateurActifAsync(CancellationToken ct = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT EXISTS(SELECT 1 FROM Utilisateur WHERE Role=$role AND Actif=1)"; cmd.Parameters.AddWithValue("$role",Roles.Administrateur); return Convert.ToInt64(await cmd.ExecuteScalarAsync(ct))==1; }
    static void Add(SqliteCommand cmd, Utilisateur u, string password) { cmd.Parameters.AddWithValue("$id",u.Id.ToString()); cmd.Parameters.AddWithValue("$login",u.NomUtilisateur); cmd.Parameters.AddWithValue("$nom",u.NomComplet); cmd.Parameters.AddWithValue("$role",u.Role); cmd.Parameters.AddWithValue("$actif",u.Actif?1:0); cmd.Parameters.AddWithValue("$now",DateTime.UtcNow.ToString("O")); cmd.Parameters.AddWithValue("$hash",PasswordHasher.Hash(password)); }
    static Utilisateur Read(SqliteDataReader r)=>new(Guid.Parse(r.GetString(0)),r.GetString(1),r.GetString(2),r.GetString(3),r.GetInt64(4)==1);
}

public sealed class SqliteCategoryRepository(SqliteConnectionFactory factory) : ICategorieRepository
{
    public async Task<Categorie?> GetByIdAsync(Guid id, CancellationToken ct=default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,Nom,Active FROM Categorie WHERE Id=$id"; cmd.Parameters.AddWithValue("$id",id.ToString()); await using var r=await cmd.ExecuteReaderAsync(ct); return await r.ReadAsync(ct)?new Categorie(Guid.Parse(r.GetString(0)),r.GetString(1),r.GetInt64(2)==1):null; }
    public async Task<IReadOnlyList<Categorie>> ListerAsync(CancellationToken ct=default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,Nom,Active FROM Categorie ORDER BY Nom"; var list=new List<Categorie>(); await using var r=await cmd.ExecuteReaderAsync(ct); while(await r.ReadAsync(ct)) list.Add(new Categorie(Guid.Parse(r.GetString(0)),r.GetString(1),r.GetInt64(2)==1)); return list; }
    public Task AjouterAsync(Categorie x,CancellationToken ct=default)=>Exec("INSERT INTO Categorie(Id,Nom,Active,CreeLeUtc,ModifieLeUtc) VALUES($id,$nom,$active,$now,$now)",x,ct);
    public Task ModifierAsync(Categorie x,CancellationToken ct=default)=>Exec("UPDATE Categorie SET Nom=$nom,Active=$active,ModifieLeUtc=$now WHERE Id=$id",x,ct);
    async Task Exec(string sql,Categorie x,CancellationToken ct) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText=sql; cmd.Parameters.AddWithValue("$id",x.Id.ToString()); cmd.Parameters.AddWithValue("$nom",x.Nom); cmd.Parameters.AddWithValue("$active",x.Active?1:0); cmd.Parameters.AddWithValue("$now",DateTime.UtcNow.ToString("O")); await cmd.ExecuteNonQueryAsync(ct); }
}

public sealed class SqliteProductRepository(SqliteConnectionFactory factory) : IProduitRepository
{
    public async Task<Produit?> GetByIdAsync(Guid id,CancellationToken ct=default) { var rows=await RechercherAsync(new ProduitFilter(),ct); return rows.FirstOrDefault(x=>x.Id==id); }
    public async Task<IReadOnlyList<Produit>> RechercherAsync(ProduitFilter f,CancellationToken ct=default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT p.Id,p.Reference,p.Nom,p.CategorieId,p.PrixVenteFcfa,p.SeuilAlerte,p.CreeLeUtc,p.Actif,COALESCE((SELECT SUM(Quantite) FROM MouvementStock m WHERE m.ProduitId=p.Id),0) FROM Produit p WHERE ($search='' OR p.Reference LIKE $like OR p.Nom LIKE $like) AND ($cat='' OR p.CategorieId=$cat) AND ($actif=-1 OR p.Actif=$actif) AND ($dispo=-1 OR (($stock>0 AND (SELECT COALESCE(SUM(Quantite),0) FROM MouvementStock m2 WHERE m2.ProduitId=p.Id)>0) OR ($stock=0 AND (SELECT COALESCE(SUM(Quantite),0) FROM MouvementStock m3 WHERE m3.ProduitId=p.Id)<=0))) ORDER BY p.Nom"; var s=f.Recherche?.Trim()??""; cmd.Parameters.AddWithValue("$search",s); cmd.Parameters.AddWithValue("$like",$"%{s}%"); cmd.Parameters.AddWithValue("$cat",f.CategorieId?.ToString()??""); cmd.Parameters.AddWithValue("$actif",f.Actif is null?-1:(f.Actif.Value?1:0)); cmd.Parameters.AddWithValue("$dispo",f.Disponible is null?-1:(f.Disponible.Value?1:0)); cmd.Parameters.AddWithValue("$stock",f.Disponible==true?1:0); var list=new List<Produit>(); await using var r=await cmd.ExecuteReaderAsync(ct); while(await r.ReadAsync(ct)) list.Add(new Produit(Guid.Parse(r.GetString(0)),r.GetString(1),r.GetString(2),r.IsDBNull(3)?null:Guid.Parse(r.GetString(3)),r.GetInt64(4),r.GetInt32(5),DateTime.Parse(r.GetString(6),null,System.Globalization.DateTimeStyles.RoundtripKind),r.GetInt64(7)==1)); return list; }
    public async Task AjouterAsync(Produit p,CancellationToken ct=default)=>await Save(p,"INSERT INTO Produit(Id,Reference,Nom,CategorieId,PrixVenteFcfa,SeuilAlerte,Actif,CreeLeUtc,ModifieLeUtc) VALUES($id,$ref,$nom,$cat,$prix,$seuil,$actif,$now,$now)",ct);
    public async Task ModifierAsync(Produit p,CancellationToken ct=default)=>await Save(p,"UPDATE Produit SET Reference=$ref,Nom=$nom,CategorieId=$cat,PrixVenteFcfa=$prix,SeuilAlerte=$seuil,Actif=$actif,ModifieLeUtc=$now WHERE Id=$id",ct);
    async Task Save(Produit p,string sql,CancellationToken ct) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText=sql; cmd.Parameters.AddWithValue("$id",p.Id.ToString()); cmd.Parameters.AddWithValue("$ref",p.Reference); cmd.Parameters.AddWithValue("$nom",p.Nom); cmd.Parameters.AddWithValue("$cat",(object?)p.CategorieId?.ToString()??DBNull.Value); cmd.Parameters.AddWithValue("$prix",p.PrixVenteFcfa); cmd.Parameters.AddWithValue("$seuil",p.SeuilAlerte); cmd.Parameters.AddWithValue("$actif",p.Actif?1:0); cmd.Parameters.AddWithValue("$now",DateTime.UtcNow.ToString("O")); await cmd.ExecuteNonQueryAsync(ct); }
}

public sealed class SqliteStockRepository(SqliteConnectionFactory factory) : IStockRepository
{
    public async Task<int> ObtenirStockAsync(Guid id,CancellationToken ct=default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT COALESCE(SUM(Quantite),0) FROM MouvementStock WHERE ProduitId=$id"; cmd.Parameters.AddWithValue("$id",id.ToString()); return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct)); }
    public async Task<IReadOnlyList<MouvementStockDto>> ListerAsync(Guid? productId=null,CancellationToken ct=default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,ProduitId,Quantite,Type,COALESCE(Motif,''),UtilisateurId,DateTechniqueUtc,QuantiteAvant,QuantiteComptee,ReferenceSource FROM MouvementStock WHERE ($p='' OR ProduitId=$p) ORDER BY DateTechniqueUtc DESC"; cmd.Parameters.AddWithValue("$p",productId?.ToString()??""); var list=new List<MouvementStockDto>(); var running=0; await using var r=await cmd.ExecuteReaderAsync(ct); while(await r.ReadAsync(ct)) { var m=new MouvementStock(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),r.GetInt32(2),r.GetString(3),r.GetString(4),Guid.Parse(r.GetString(5)),DateTime.Parse(r.GetString(6),null,System.Globalization.DateTimeStyles.RoundtripKind),r.IsDBNull(7)?null:r.GetInt32(7),r.IsDBNull(8)?null:r.GetInt32(8),r.IsDBNull(9)?null:r.GetString(9)); running+=m.Quantite; list.Add(new MouvementStockDto(m,running)); } return list; }
    public async Task AjouterMouvementAsync(MouvementStock m,CancellationToken ct=default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="INSERT INTO MouvementStock(Id,ProduitId,Quantite,Type,Motif,QuantiteAvant,QuantiteComptee,ReferenceSource,UtilisateurId,DateTechniqueUtc) VALUES($id,$p,$q,$t,$motif,$avant,$comptee,$source,$u,$d)"; cmd.Parameters.AddWithValue("$id",m.Id.ToString()); cmd.Parameters.AddWithValue("$p",m.ProduitId.ToString()); cmd.Parameters.AddWithValue("$q",m.Quantite); cmd.Parameters.AddWithValue("$t",m.Type); cmd.Parameters.AddWithValue("$motif",m.Motif); cmd.Parameters.AddWithValue("$avant",(object?)m.QuantiteAvant??DBNull.Value); cmd.Parameters.AddWithValue("$comptee",(object?)m.QuantiteComptee??DBNull.Value); cmd.Parameters.AddWithValue("$source",(object?)m.ReferenceSource??DBNull.Value); cmd.Parameters.AddWithValue("$u",m.UtilisateurId.ToString()); cmd.Parameters.AddWithValue("$d",m.DateTechniqueUtc.ToUniversalTime().ToString("O")); await cmd.ExecuteNonQueryAsync(ct); }
}
